    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260316082952_InitialCreate') THEN
    CREATE TABLE "Bills" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(200) NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "DueDate" timestamp with time zone NOT NULL,
        "IsPaid" boolean NOT NULL DEFAULT FALSE,
        "IsRecurring" boolean NOT NULL DEFAULT FALSE,
        "RecurringFrequency" integer,
        "Notes" character varying(1000),
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
        "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
        "OwnerId" integer NOT NULL,
        "CategoryId" integer NOT NULL,
        CONSTRAINT "PK_Bills" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Bills_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Bills_Users_OwnerId" FOREIGN KEY ("OwnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

